input.command:
cd /workspace/dataset
run() { echo "### argv: [$*]"; out=$(./test5_executable "$@" 2>/dev/null); rc1=$?; err=$(./test5_executable "$@" 2>&1 1>/dev/null); echo "OUT:[$out]"; echo "ERR:[$err]"; echo "rc=$rc1"; }
for v in "-0" "-12" "-.5" "-1." "-1e5" "-1_0" "--1" "-+1" "-0.0" "-00" "-9999999999999" "-1.5.5" "- " " -x" "-x y" "-a b" "-1 2" "-" "--" "---" "-h" "-hh" "-help"; do run --a bc --b "$v"; done
